    "front_loaded_tools": {
      "type": "string",
      "title": "Front-loaded lean-ctx tools",
      "description": "Lean-ctx MCP tool names to keep in the prompt; all other lean-ctx tools stay deferred.",
      "multiple": true,
      "default": [
        "ctx_read",
        "ctx_search",
        "ctx_shell",
        "ctx_compose",
        "ctx_callgraph",
        "ctx_session"
      ]
    },
    "shape_native_output": {
      "type": "boolean",
      "title": "Shape native Bash output",
      "description": "Compress large native Bash stdout through lean-ctx (recoverable); off keeps it byte-for-byte.",
      "default": true
    },
    "cockpit_panel": {
      "type": "boolean",
      "title": "Open the LeanCTX cockpit sidebar",
      "description": "Open the cockpit sidebar when a session starts. /cockpit off and /cockpit on change it; /cockpit opens it once either way.",
